SELECT PMST, PMKY, PMCO, PMNM, PMV1, PMV2, PMV3, PMV4, PMV5,INSERTTIMESTAMP, UPDATETIMESTAMP ,
	 (SELECT COUNT(1) FROM PARAMETER T1 WHERE PMST ='SYSTEM' AND PMKY ='DS_CITYCODE' AND T1.PMV1 = T2.PMCO)LEAFNUM
 FROM PARAMETER T2
WHERE  PMCO NOT LIKE '%****%'

	AND PMST =#{dto.pmst,jdbcType=VARCHAR}


	AND PMKY =#{dto.pmky,jdbcType=VARCHAR}


	AND PMCO =#{dto.pmco,jdbcType=VARCHAR}


	AND pmv1 =#{dto.pmv1,jdbcType=VARCHAR}


	AND pmv2 =#{dto.pmv2,jdbcType=VARCHAR}

SELECT PMST, PMKY, PMCO, PMNM, PMV1, PMV2, PMV3
FROM PARAMETER
WHERE  
	PMST =#{dto.pmst}
AND PMKY =#{dto.pmky}
AND PMCO =#{dto.pmco}

SELECT T.CUSTSER_ID, T.CUSTSER_NAME, T.CUSTSER_MOBILE, T.CUSTSER_WORKYEAR, T.CUSTSER_ADDRESS, T.CUSTSER_PHOTO, T.CUSTSER_NICKNAME, T.CUSTSER_PERSONAL_QRCODE FROM CMWA_CUSTSERVICE_INFO T WHERE 1=1
AND T.CUSTSER_ID =#{map.custserId,jdbcType=VARCHAR}
AND T.CUSTSER_TYPE =#{map.custserType,jdbcType=VARCHAR}
AND T.CUSTSER_DEFAULT =#{map.state,jdbcType=CHAR}
ORDER BY T.UPDATE_DATE DESC

mapper.update:
UPDATE PARAMETER
   SET PMNM = PMNM -1
 WHERE PMST =#{dto.pmst}
 AND PMKY =#{dto.pmky}
 AND PMCO =#{dto.pmco}
 AND to_number(PMNM) >0

 UPDATE PARAMETER
  	SET PMCO = PMCO -1
 WHERE 
	 PMKY =#{dto.pmky}
	 AND PMCO =#{dto.pmco}
	 AND to_number(PMCO) >0

